using System;
using System.Linq;
using System.Threading.Tasks;
using UnityEngine;
public static class ValidateVehicleV6Audio {
public static async Task<string> Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var v=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var a=v.GetComponent<VehicleAudio>();if(a==null||!a.RecordedEngine||a.profile.engineBands.Length!=5)throw new Exception("Recorded engine bands absent");float minimumRms=1;foreach(var band in a.profile.engineBands)foreach(var clip in new[]{band.coast,band.loaded}){var data=new float[clip.samples*clip.channels];if(!clip.GetData(data,0))throw new Exception("Decode failed "+clip.name);double sum=0;foreach(var x in data){if(float.IsNaN(x)||Mathf.Abs(x)>.99f)throw new Exception("Clipped "+clip.name);sum+=x*x;}float rms=Mathf.Sqrt((float)(sum/data.Length));if(rms<.01f)throw new Exception("Silent clip "+clip.name);minimumRms=Mathf.Min(minimumRms,rms);}var input=v.Input;bool external=v.externalControl,neutral=v.Neutral,reverse=v.ReverseGear,low=v.LowRange;int gear=v.Gear;double dsp=AudioSettings.dspTime;float high=0,highWeight=0,energy=0;int frames=Time.frameCount;try{v.externalControl=true;v.SetNeutral(true);v.SetInput(new VehicleControlInput{handbrake=true});await Task.Delay(6000);float idle=v.EngineRpm;v.SetInput(new VehicleControlInput{throttle=1,handbrake=true});for(int n=0;n<40;n++){await Task.Delay(100);high=Mathf.Max(high,v.EngineRpm);highWeight=Mathf.Max(highWeight,a.LoadedBands[4].volume+a.CoastBands[4].volume);var output=new float[1024];foreach(var source in a.LoadedBands.Concat(a.CoastBands)){source.GetOutputData(output,0);energy+=output.Sum(x=>x*x);if(source.pitch<.1f||source.pitch>1.66f)throw new Exception("Invalid sample pitch");}}v.SetInput(new VehicleControlInput{handbrake=true});await Task.Delay(6000);float released=v.EngineRpm;if(high<6000||highWeight<.05f||released>high-500)throw new Exception("RPM mix failed high="+high+" gain="+highWeight+" released="+released);if(a.idle.isPlaying||a.load.isPlaying)throw new Exception("Legacy engine loops still playing");if(a.profile.brakeAir!=null)throw new Exception("Pneumatic brakes on Pajero");if(AudioSettings.dspTime<=dsp||Time.frameCount<=frames||energy<.00001f)throw new Exception("DSP/game not advancing or no engine output");if(a.CoastBands.Any(s=>!s.isPlaying)||a.LoadedBands.Any(s=>!s.isPlaying))throw new Exception("Loops stopped");return "PASS 10 recorded loops decode, min RMS="+minimumRms.ToString("F3")+"; actual engine "+idle.ToString("F0")+" -> "+high.ToString("F0")+" -> "+released.ToString("F0")+" RPM; high-band gain="+highWeight.ToString("F3")+"; decoded source energy="+energy.ToString("F3")+"; DSP/frame advanced; diesel loops silent; pneumatic brakes absent; 5 coast/load bands playing.";}finally{v.SetInput(input);v.SetTransmission(reverse,low);v.SetNeutral(neutral);if(!neutral){v.Shift(gear-v.Gear);}v.externalControl=external;}}
}
